/* Stranded II service worker (generated by tools/build.mjs — edit src/sw.template.js).
 * Everything the game needs is cached at install, so it plays offline. Each build has its own
 * cache name; a new build installs in the background and takes over on the next launch.
 * (The page checks this too: index.html carries its build, and if the offline copy here is another
 * build's it drops it and loads again from the network. See the script in index.html.) */
const CACHE = 'stranded2-__CACHE_VERSION__';
// What the game cannot start without: all of it, or the install fails and is tried again.
const SHELL = __SHELL__;
// The rest (the planet's data, the models): fetched one by one, and one that does not arrive is fetched when the
// game asks for it. (All in one all-or-nothing batch, a single dropped request among fifty failed the install,
// and a failed install leaves the old build in charge.)
const PRECACHE = __PRECACHE__;
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE)
    .then((c) => c.addAll(SHELL).then(() => Promise.all(PRECACHE.map((u) => c.add(u).catch(() => {})))))
    .then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    // older builds of this game go; the first game's cache goes too, unless this is a preview living beside it
    .then((keys) => Promise.all(keys.filter((k) => (k.startsWith('stranded2-') && k !== CACHE) || (k.startsWith('stranded-') && !/\/next\/$/.test(self.registration.scope)))
      .map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || !req.url.startsWith(self.location.origin)) return;
  // the worker's own script is never answered from here: what asks for it wants to know what is published
  if (/\/sw\.js(\?|$)/.test(req.url)) return;
  // the page itself: network first, so a new build is noticed as soon as there is a connection
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).then((res) => {
      if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put('./', copy)); }
      return res;
    }).catch(() => caches.open(CACHE).then((c) => c.match('./'))));
    return;
  }
  // everything else: this build's cache first, and no other build's (file names are stable, the cache name is not)
  e.respondWith(caches.open(CACHE).then((c) => c.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res && res.ok) c.put(req, res.clone());
    return res;
  }))));
});
